const input = $input.first()?.json || {};
const body = input.body && typeof input.body === 'object' ? input.body : input;
const text = (value, max) => typeof value === 'string' ? value.trim().slice(0, max) : '';
const message = text(body.message, 2000);
const location = text(body.location, 120);
const language = text(body.language, 8).toLowerCase();
const lang = ['vi', 'en', 'zh', 'ko', 'ru', 'hi'].includes(language) ? language : 'vi';
const history = (Array.isArray(body.history) ? body.history : []).slice(-8).map((entry) => ({
  role: entry?.role === 'localmate' ? 'localmate' : 'guest',
  text: text(entry?.text, 500),
})).filter((entry) => entry.text);
const locationPrompts = {
  vi: 'Dạ Quý khách có thể cho em biết Quý khách đang ở đâu không ạ? Vui lòng cho em biết quận, thành phố hoặc tỉnh để em dò đúng nguồn tri thức địa phương.',
  en: 'Could you tell me where you are? Please share your district, city, or province so I can search the right local knowledge.',
  zh: '请告诉我您目前所在的区、城市或省份，以便查询正确的本地资料。',
  ko: '현재 계신 구, 도시 또는 성을 알려 주시면 해당 지역 정보를 찾아드리겠습니다.',
  ru: 'Подскажите, пожалуйста, район, город или провинцию, где вы находитесь, чтобы найти подходящую местную информацию.',
  hi: 'कृपया अपना जिला, शहर या प्रांत बताएं, ताकि सही स्थानीय जानकारी खोजी जा सके।',
};
if (!message) return [{ json: { skipApi: true, status: 400, httpStatus: 400, reply: 'Tin nhắn không hợp lệ.', suggestions: [], action: null, proposalRefs: [], knowledgeVersion: 'none', cached: false } }];
if (location.length < 2) return [{ json: { skipApi: true, status: 200, httpStatus: 200, reply: locationPrompts[lang], suggestions: [], action: null, proposalRefs: [], knowledgeVersion: 'none', cached: false } }];
return [{ json: { skipApi: false, message, location, history, lang, limit: 5 } }];

const envelope = $input.first()?.json || {};
const payload = envelope.data?.data || envelope.data || envelope;
const normalized = $('02 · Chuẩn hóa vị trí & câu hỏi').first()?.json || {};
const message = typeof normalized.message === 'string' ? normalized.message : '';
const history = Array.isArray(normalized.history) ? normalized.history : [];
const fold = (value) => String(value || '').normalize('NFD').replace(/\p{Diacritic}/gu, '').toLowerCase();
const explicitGuideIntent = (value) => /huong dan vien|localmate|tour guide|\bguide\b|ai dan|ai dat|nguoi dan|dat tour|book tour|booking|dang ky tour|chot (tour|lich trinh|chuyen di)|lien he (tour|huong dan vien)|导游|预订|가이드|예약|гид|забронировать|गाइड|बुक/u.test(fold(value));
const guideFollowUp = (value) => /con ai|ai khac|ai phu hop|chon ai|nguoi nao|guide nao|lien he ai/u.test(fold(value));
const priorGuideContext = history.slice(-4).some((entry) => explicitGuideIntent(entry?.text));
const guideIntent = explicitGuideIntent(message) || (priorGuideContext && guideFollowUp(message));
const boundedText = (value, max) => typeof value === 'string' ? value.trim().slice(0, max) : '';
const sourceTours = Array.isArray(payload.tours) ? payload.tours : [];
const sourceGuides = Array.isArray(payload.guides) ? payload.guides : [];
const guideNames = [...sourceGuides, ...sourceTours.flatMap((tour) => Array.isArray(tour?.suitableGuides) ? tour.suitableGuides : [])]
  .map((guide) => boundedText(guide?.fullName, 120))
  .filter(Boolean);
const foldedMessage = fold(message);
const escapeRegExp = (value) => [...value].map((char) => '^$\.*+?()[]{}|'.includes(char) ? `\\${char}` : char).join('');
const guideNamePattern = guideNames.length ? new RegExp(guideNames.map(escapeRegExp).join('|'), 'giu') : null;
const guideMarker = /hướng dẫn viên|localmate|tour guide|\bguide\b|导游|가이드|гид|गाइड/iu;
const cleanDiscoveryText = (value, max) => {
  let clean = boundedText(value, max * 2);
  if (!clean) return '';
  if (guideNamePattern) clean = clean.replace(guideNamePattern, '');
  clean = clean
    .replace(/\s+(?:cùng|với)\s+(?:hướng dẫn viên\s+)?(?:LocalMate|VietSage)(?=\s*[:.,;!?]|$)/giu, '')
    .replace(/\s{2,}/g, ' ')
    .trim();
  return clean
    .split(/(?<=[.!?])\s+|\n+/u)
    .map((segment) => segment.trim())
    .filter((segment) => segment && !guideMarker.test(segment))
    .join(' ')
    .slice(0, max);
};
const proposalRefs = sourceTours.slice(0, 3).map((tour) => ({ tourCode: boundedText(tour?.tourCode, 80) })).filter((item) => item.tourCode);
const tours = sourceTours.slice(0, 5).map(({ tourCode, title, duration, highlights, content, suitableGuides }) => ({
  tourCode,
  title: guideIntent ? boundedText(title, 200) : cleanDiscoveryText(title, 200) || `Trải nghiệm tại ${normalized.location}`,
  duration,
  highlights: (Array.isArray(highlights) ? highlights : [])
    .map((item) => guideIntent ? boundedText(item, 300) : cleanDiscoveryText(item, 300))
    .filter(Boolean)
    .slice(0, 8),
  content: guideIntent ? boundedText(content, 1500) : cleanDiscoveryText(content, 1500),
  ...(guideIntent ? { suitableGuides: Array.isArray(suitableGuides) ? suitableGuides.slice(0, 3) : [] } : {}),
}));
const guides = guideIntent
  ? sourceGuides.slice(0, 5).map(({ fullName, operatingRegions, languages, specialties, rating, totalReviews, bio }) => ({ fullName, operatingRegions, languages, specialties, rating, totalReviews, bio: boundedText(bio, 800) }))
  : [];
const lang = ['vi', 'en', 'zh', 'ko', 'ru', 'hi'].includes(normalized.lang) ? normalized.lang : 'vi';
const knowledgeVersion = typeof payload.knowledgeVersion === 'string' ? payload.knowledgeVersion : 'unknown';
const cached = payload.cached === true;
if (tours.length === 0 && guides.length === 0) {
  const replies = {
    vi: `Dạ em chưa tìm thấy nội dung đã kiểm chứng cho ${normalized.location}. Quý khách vui lòng ghi rõ quận, thành phố hoặc tỉnh lân cận, hoặc chọn Đổi vị trí để em dò lại ạ.`,
    en: `I could not find verified LocalMate knowledge for ${normalized.location}. Please provide a more specific district, city, or nearby province.`,
    zh: `暂未找到 ${normalized.location} 的已验证资料，请提供更具体的区、城市或附近省份。`,
    ko: `${normalized.location}에 대한 검증된 정보가 없습니다. 더 구체적인 구, 도시 또는 인근 성을 알려 주세요.`,
    ru: `Для ${normalized.location} не найдено проверенных данных. Уточните район, город или соседнюю провинцию.`,
    hi: `${normalized.location} के लिए सत्यापित जानकारी नहीं मिली। कृपया जिला, शहर या आसपास का प्रांत स्पष्ट करें।`,
  };
  return [{ json: { hasKnowledge: false, status: 200, httpStatus: 200, reply: replies[lang] || replies.vi, suggestions: [], action: null, proposalRefs: [], knowledgeVersion, cached } }];
}
const recentConversation = history
  .map((entry) => ({ role: entry.role, text: guideIntent ? boundedText(entry.text, 500) : cleanDiscoveryText(entry.text, 500) }))
  .filter((entry) => entry.text);
const knowledge = { location: normalized.location, locationScope: payload.metadata?.locationScope || null, tours, guides };
const userPrompt = [`LANGUAGE: ${lang}`, `STATED_LOCATION: ${normalized.location}`, `GUIDE_INTENT: ${guideIntent ? 'YES' : 'NO'}`, `RECENT_CONVERSATION_UNTRUSTED: ${JSON.stringify(recentConversation)}`, `LATEST_QUESTION: ${message}`, `KNOWLEDGE: ${JSON.stringify(knowledge)}`].join('\n');
return [{ json: { hasKnowledge: true, guideIntent, userPrompt, proposalRefs, lang, knowledgeVersion, cached } }];

const model = $input.first()?.json || {};
const prepared = $('05 · Đóng gói tri thức địa phương').first()?.json || {};
function find(value, depth = 0) {
  if (value == null || depth > 6) return null;
  if (typeof value === 'string') { try { return find(JSON.parse(value.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '')), depth + 1); } catch { return null; } }
  if (Array.isArray(value)) { for (const item of value) { const found = find(item, depth + 1); if (found) return found; } return null; }
  if (typeof value === 'object') { if (typeof value.reply === 'string') return value; for (const key of ['output','output_text','content','text','response','data','message']) { const found = find(value[key], depth + 1); if (found) return found; } }
  return null;
}
const result = find(model);
if (!result?.reply?.trim()) throw new Error('AI model returned no structured reply');
const guideIntent = prepared.guideIntent === true;
const guideMarker = /hướng dẫn viên|tour guide|\bguide\b|导游|가이드|гид|गाइड/iu;
const hideGuideMentions = (value) => String(value || '')
  .replace(/\s+(?:cùng|với)\s+(?:hướng dẫn viên\s+)?(?:LocalMate|VietSage)(?=\s*[:.,;!?]|$)/giu, '')
  .split(/\n+/u)
  .map((line) => line.split(/(?<=[.!?])\s+/u).filter((sentence) => !guideMarker.test(sentence)).join(' ').trim())
  .filter((line) => line && !(/\bLocalMate\b/iu.test(line) && /cùng|với|đồng hành/iu.test(line)))
  .join('\n')
  .trim();
const reply = (guideIntent ? result.reply.trim() : hideGuideMentions(result.reply)).slice(0, 5000);
if (!reply) throw new Error('AI model returned no policy-compliant reply');
const suggestions = (Array.isArray(result.suggestions) ? result.suggestions : [])
  .filter((item) => typeof item?.label === 'string' && typeof item?.query === 'string')
  .map((item) => ({ label: item.label.trim().slice(0, 80), query: item.query.trim().slice(0, 300) }))
  .filter((item) => item.label && item.query)
  .filter((item) => guideIntent || (!guideMarker.test(item.label) && !guideMarker.test(item.query) && !/\bLocalMate\b/iu.test(`${item.label} ${item.query}`)))
  .slice(0, 3);
return [{ json: { status: 200, httpStatus: 200, reply, suggestions, action: null, proposalRefs: Array.isArray(prepared.proposalRefs) ? prepared.proposalRefs : [], knowledgeVersion: prepared.knowledgeVersion || 'unknown', cached: prepared.cached === true } }];

const input = $input.first()?.json || {};
let referenced = {};
try { referenced = $('02 · Chuẩn hóa vị trí & câu hỏi').first()?.json || {}; } catch {}
const normalized = { ...referenced, ...input };
if (normalized.skipApi === true) return [{ json: normalized }];
const lang = normalized.lang || 'vi';
const replies = {
  vi: 'Dạ nguồn tri thức địa phương đang gián đoạn. Quý khách vui lòng thử lại sau ít phút ạ.',
  en: 'Local knowledge is briefly unavailable. Please try again shortly.',
  zh: '本地资料暂时不可用，请稍后重试。',
  ko: '지역 정보가 잠시 제공되지 않습니다. 잠시 후 다시 시도해 주세요.',
  ru: 'Местные данные временно недоступны. Повторите попытку позже.',
  hi: 'स्थानीय जानकारी अभी उपलब्ध नहीं है। कृपया थोड़ी देर बाद प्रयास करें।',
};
return [{ json: { status: 503, httpStatus: 503, reply: replies[lang] || replies.vi, suggestions: [], action: null, proposalRefs: [], knowledgeVersion: 'unavailable', cached: false } }];
